.box {
  display: flex;
  justify-content: center;
  align-items: center;
}

.stack {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 300px;
}

/* bug */
.row {
  justify-content: space-between;
}
/* fix */
.row {
  display: flex;
  justify-content: space-between;
}

/* before */
.item {
  flex-grow: 1;
  flex-shrink: 1;
  flex-basis: 0%;
}
/* after */
.item {
  flex: 1;
}

.item {
  flex: 1;
  min-width: 0;
}
.item p {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.row {
  display: flex;
  align-items: flex-start;
}
.badge {
  align-self: flex-end;
}

.box {
  display: flex;
  flex-wrap: wrap;
  height: 300px;
  align-content: flex-start;
}

/* before */
.a { margin-right: 40px; }
.b { margin-right: 40px; }
/* after */
.row {
  display: flex;
  justify-content: space-between;
}
